// 瓶子数组从左到右依次为瓶底到瓶口。规则层不依赖 wx。
const CAPACITY = 4;
function clone(bottles) { return bottles.map(b => b.slice()); }
function top(bottle) { return bottle[bottle.length - 1]; }
function topGroupSize(bottle) {
  let count = 0;
  for (let i = bottle.length - 1; i >= 0 && bottle[i] === top(bottle); i--) count++;
  return count;
}
function isBottleSolved(bottle, capacity = CAPACITY) {
  return bottle.length === 0 || (bottle.length === capacity && bottle.every(c => c === bottle[0]));
}
function isSolved(bottles, capacity = CAPACITY) {
  return bottles.every(b => isBottleSolved(b, capacity));
}
function inspectPour(bottles, from, to, capacity = CAPACITY) {
  if (!Number.isInteger(from) || !Number.isInteger(to) || !bottles[from] || !bottles[to]) return { ok: false, reason: '瓶子不存在' };
  if (from === to) return { ok: false, reason: '请选择另一只瓶子' };
  const a = bottles[from], b = bottles[to];
  if (!a.length) return { ok: false, reason: '这只瓶子是空的' };
  if (b.length >= capacity) return { ok: false, reason: '目标瓶已经满了' };
  if (b.length && top(a) !== top(b)) return { ok: false, reason: '只能倒入空瓶，或顶部颜色相同的瓶子' };
  return { ok: true, amount: Math.min(topGroupSize(a), capacity - b.length), color: top(a) };
}
function pour(bottles, from, to, capacity = CAPACITY) {
  const result = inspectPour(bottles, from, to, capacity);
  if (!result.ok) return result;
  const next = clone(bottles);
  next[to].push(...next[from].splice(next[from].length - result.amount));
  return Object.assign({}, result, { bottles: next });
}
function same(a, b) { return JSON.stringify(a) === JSON.stringify(b); }
function validateBoard(bottles, colors, capacity = CAPACITY, bottleCount = colors + 2) {
  if (!Array.isArray(bottles) || bottles.length !== bottleCount) return false;
  const counts = new Array(colors).fill(0);
  for (const b of bottles) {
    if (!Array.isArray(b) || b.length > capacity) return false;
    for (const c of b) {
      if (!Number.isInteger(c) || c < 0 || c >= colors) return false;
      counts[c]++;
    }
  }
  return counts.every(n => n === capacity);
}
module.exports = { CAPACITY, clone, top, topGroupSize, isBottleSolved, isSolved, inspectPour, pour, same, validateBoard };

