const R = require('./rules');
// 瓶子可互换：排序后的键去掉对称状态。实际路径仍保留原始瓶号。
function key(bottles) { return bottles.map(b => b.join(',')).sort().join('|'); }
function moves(bottles, capacity) {
  const list = [];
  for (let from = 0; from < bottles.length; from++) {
    const a = bottles[from];
    if (!a.length || R.isBottleSolved(a, capacity)) continue;
    let usedEmpty = false;
    for (let to = 0; to < bottles.length; to++) {
      const b = bottles[to];
      if (!b.length) {
        if (usedEmpty || R.topGroupSize(a) === a.length) continue;
        usedEmpty = true;
      }
      const result = R.pour(bottles, from, to, capacity);
      if (!result.ok) continue;
      let score = b.length ? 5 : 0;
      if (R.isBottleSolved(result.bottles[to], capacity)) score += 10;
      if (!result.bottles[from].length) score += 3;
      list.push({ from, to, bottles: result.bottles, score });
    }
  }
  return list.sort((a, b) => b.score - a.score);
}
function createSearch(bottles, options = {}) {
  const capacity = options.capacity || 4;
  const maxNodes = options.maxNodes || 16000;
  const maxDepth = options.maxDepth || 100;
  const stack = [{ bottles: R.clone(bottles), parent: null, move: null, depth: 0 }];
  const visited = new Map();
  let count = 0, done = false, answer = null, clipped = false;
  function finish(status, path) {
    done = true;
    answer = { status, path: path || [], visited: count };
    return answer;
  }
  return {
    step(budget = 200) {
      if (done) return answer;
      let work = 0;
      while (stack.length && work++ < budget) {
        if (count >= maxNodes) return finish('limit');
        const node = stack.pop(), k = key(node.bottles);
        if (visited.has(k) && visited.get(k) <= node.depth) continue;
        visited.set(k, node.depth);
        count++;
        if (R.isSolved(node.bottles, capacity)) {
          const path = [];
          for (let p = node; p.parent; p = p.parent) path.push(p.move);
          return finish('solved', path.reverse());
        }
        if (node.depth >= maxDepth) { clipped = true; continue; }
        const next = moves(node.bottles, capacity);
        for (let i = next.length - 1; i >= 0; i--) {
          const m = next[i];
          stack.push({ bottles: m.bottles, parent: node, move: [m.from, m.to], depth: node.depth + 1 });
        }
      }
      if (!stack.length) return finish(clipped ? 'limit' : 'unsolvable');
      return { status: 'searching', visited: count };
    }
  };
}
function solve(bottles, options) {
  const search = createSearch(bottles, options);
  let result;
  do { result = search.step(1000); } while (result.status === 'searching');
  return result;
}
module.exports = { key, moves, createSearch, solve };

